\documentclass[letterpaper,11pt]{article}

\usepackage{latexsym}
\usepackage[empty]{fullpage}
\usepackage{titlesec}
\usepackage{marvosym}
\usepackage[usenames,dvipsnames]{color}
\usepackage{verbatim}
\usepackage{enumitem}
\usepackage[hidelinks]{hyperref}
\usepackage{fancyhdr}
\usepackage[english]{babel}
\usepackage{tabularx}

% fontawesome
\usepackage{fontawesome5}

% fixed width
\usepackage[scale=0.90,lf]{FiraMono}

% light-grey
\definecolor{light-grey}{gray}{0.83}
\definecolor{dark-grey}{gray}{0.3}
\definecolor{text-grey}{gray}{.08}

\DeclareRobustCommand{\ebseries}{\fontseries{eb}\selectfont}
\DeclareTextFontCommand{\texteb}{\ebseries}

% custom underline
\usepackage{contour}
\usepackage[normalem]{ulem}
\renewcommand{\ULdepth}{1.8pt}
\contourlength{0.8pt}
\newcommand{\myuline}[1]{%
  \uline{\phantom{#1}}%
  \llap{\contour{white}{#1}}%
}

% custom font: helvetica-style
\usepackage{tgheros}
\renewcommand*\familydefault{\sfdefault}
\usepackage[T1]{fontenc}

\pagestyle{fancy}
\fancyhf{}
\fancyfoot{}
\renewcommand{\headrulewidth}{0pt}
\renewcommand{\footrulewidth}{0pt}

% Adjust margins
\addtolength{\oddsidemargin}{-0.5in}
\addtolength{\evensidemargin}{0in}
\addtolength{\textwidth}{1in}
\addtolength{\topmargin}{-.5in}
\addtolength{\textheight}{1.0in}

\urlstyle{same}

\raggedbottom
\raggedright
\setlength{\tabcolsep}{0in}

% sans serif sections
\titleformat{\section}{
    \bfseries \vspace{2pt} \raggedright \large
}{}{0em}{}[\color{light-grey} {\titlerule[2pt]} \vspace{-4pt}]

%-------------------------
% Custom commands
\newcommand{\resumeItem}[1]{
  \item\small{
    {#1 \vspace{-1pt}}
  }
}

\newcommand{\resumeSubheading}[4]{
  \vspace{-1pt}\item
    \begin{tabular*}{\textwidth}[t]{l@{\extracolsep{\fill}}r}
      \textbf{#1} & {\color{dark-grey}\small #2}\vspace{1pt}\\
      \textit{#3} & {\color{dark-grey} \small #4}\\
    \end{tabular*}\vspace{-4pt}
}

\newcommand{\resumeProjectHeading}[2]{
    \item
    \begin{tabular*}{\textwidth}{l@{\extracolsep{\fill}}r}
      #1 & {\color{dark-grey}} \\
    \end{tabular*}\vspace{-4pt}
}

\newcommand{\resumeSubItem}[1]{\resumeItem{#1}\vspace{-4pt}}

\renewcommand\labelitemii{$\vcenter{\hbox{\tiny$\bullet$}}$}

\newcommand{\resumeSubHeadingListStart}{\begin{itemize}[leftmargin=0in, label={}]}
\newcommand{\resumeSubHeadingListEnd}{\end{itemize}}
\newcommand{\resumeItemListStart}{\begin{itemize}}
\newcommand{\resumeItemListEnd}{\end{itemize}\vspace{0pt}}

\color{text-grey}

%-------------------------------------------
%%%%%%  RESUME STARTS HERE  %%%%%%%%%%%%%%%%%%%%%%%%%%%%

\begin{document}

%----------HEADING----------
\begin{center}
    \textbf{\Huge {{escapeLaTeX basics.name}} } \\ \vspace{5pt}
    \small
    {{#if basics.phone}}\faPhone* \texttt{ {{escapeLaTeX basics.phone}} }{{/if}}{{#if basics.email}}{{#if basics.phone}} $|$ {{/if}}\faEnvelope\ \texttt{ {{escapeLaTeX basics.email}} }{{/if}}{{#if basics.url}}{{#if basics.email}} $|$ {{/if}}\faGlobe\ \texttt{ {{escapeLaTeX basics.url}} }{{/if}}{{#if basics.location.city}}{{#if basics.url}} $|$ {{/if}}\faMapMarker*\ \texttt{ {{escapeLaTeX basics.location.city}} }{{/if}}
    {{#if basics.profiles}}\\ \vspace{2pt}
    {{#each basics.profiles}}\faLink\ \href{ {{url}} }{ {{escapeLaTeX network}} }{{#unless @last}} $|$ {{/unless}}{{/each}}
    {{/if}}
    \\ \vspace{-3pt}
\end{center}

{{#if basics.summary}}
\section{PERFIL}
  \begin{itemize}[leftmargin=0in, label={}]
    \small{\item{ {{escapeLaTeX basics.summary}} }}
  \end{itemize}
{{/if}}

%--- SECTIONS (respects user-defined order) ---
{{#each _sectionOrder}}
{{#if (eq this "work")}}
{{#if (notEmpty @root.work)}}
\section{EXPERIENCIA}
  \resumeSubHeadingListStart
{{#each @root.work}}
    \resumeSubheading
      { {{escapeLaTeX name}} }{ {{formatDate startDate}} -- {{#if endDate}}{{formatDate endDate}}{{else}}Actualidad{{/if}} }
      { {{escapeLaTeX position}} }{ {{#if location}}{{escapeLaTeX location}}{{/if}} }
{{#if (notEmpty highlights)}}
      \resumeItemListStart
{{#each highlights}}
        \resumeItem{ {{escapeLaTeX this}} }
{{/each}}
      \resumeItemListEnd
{{/if}}
{{/each}}
  \resumeSubHeadingListEnd
{{/if}}
{{else if (eq this "projects")}}
{{#if (notEmpty @root.projects)}}
\section{PROYECTOS}
    \resumeSubHeadingListStart
{{#each @root.projects}}
      \resumeProjectHeading
          {\textbf{ {{escapeLaTeX name}} }{{#if description}} $|$ \textit{\small {{escapeLaTeX description}} }{{/if}} }{ {{#if startDate}}{{formatDate startDate}}{{/if}}{{#if endDate}} -- {{formatDate endDate}}{{/if}} }
{{#if (notEmpty highlights)}}
          \resumeItemListStart
{{#each highlights}}
            \resumeItem{ {{escapeLaTeX this}} }
{{/each}}
          \resumeItemListEnd
{{/if}}
{{/each}}
    \resumeSubHeadingListEnd
{{/if}}
{{else if (eq this "education")}}
{{#if (notEmpty @root.education)}}
\section{EDUCACI\'{O}N}
  \resumeSubHeadingListStart
{{#each @root.education}}
    \resumeSubheading
      { {{escapeLaTeX institution}} }{ {{formatDate startDate}} -- {{#if endDate}}{{formatDate endDate}}{{else}}Actualidad{{/if}} }
      { {{escapeLaTeX studyType}} en {{escapeLaTeX area}} }{ {{#if location}}{{escapeLaTeX location}}{{/if}} }
{{#if (notEmpty courses)}}
      \resumeItemListStart
        \resumeItem{\textbf{Cursos}: {{join courses ", "}} }
      \resumeItemListEnd
{{/if}}
{{/each}}
  \resumeSubHeadingListEnd
{{/if}}
{{else if (eq this "skills")}}
{{#if (notEmpty @root.skills)}}
\section{HABILIDADES}
 \begin{itemize}[leftmargin=0in, label={}]
    \small{\item{
{{#each @root.skills}}
     \textbf{ {{escapeLaTeX name}} } {{#if (notEmpty keywords)}}{: {{join keywords ", "}} }\vspace{2pt} \\{{else}}\\ {{/if}}
{{/each}}
    }}
 \end{itemize}
{{/if}}
{{else if (eq this "languages")}}
{{#if (notEmpty @root.languages)}}
\section{IDIOMAS}
 \begin{itemize}[leftmargin=0in, label={}]
    \small{\item{
{{#each @root.languages}}
     \textbf{ {{escapeLaTeX language}} }{{#if fluency}}{: {{escapeLaTeX fluency}} }{{/if}}\vspace{2pt} \\
{{/each}}
    }}
 \end{itemize}
{{/if}}
{{else if (eq this "volunteer")}}
{{#if (notEmpty @root.volunteer)}}
\section{VOLUNTARIADO}
  \resumeSubHeadingListStart
{{#each @root.volunteer}}
    \resumeSubheading
      { {{escapeLaTeX organization}} }{ {{formatDate startDate}} -- {{#if endDate}}{{formatDate endDate}}{{else}}Actualidad{{/if}} }
      { {{escapeLaTeX position}} }{}
{{#if (notEmpty highlights)}}
      \resumeItemListStart
{{#each highlights}}
        \resumeItem{ {{escapeLaTeX this}} }
{{/each}}
      \resumeItemListEnd
{{/if}}
{{/each}}
  \resumeSubHeadingListEnd
{{/if}}
{{else if (eq this "awards")}}
{{#if (notEmpty @root.awards)}}
\section{PREMIOS}
  \resumeSubHeadingListStart
{{#each @root.awards}}
    \resumeProjectHeading
      {\textbf{ {{escapeLaTeX title}} }{{#if awarder}} $|$ \textit{\small {{escapeLaTeX awarder}} }{{/if}} }{ {{#if date}}{{formatDate date}}{{/if}} }
{{#if summary}}
      \resumeItemListStart
        \resumeItem{ {{escapeLaTeX summary}} }
      \resumeItemListEnd
{{/if}}
{{/each}}
  \resumeSubHeadingListEnd
{{/if}}
{{else if (eq this "certificates")}}
{{#if (notEmpty @root.certificates)}}
\section{CERTIFICADOS}
  \resumeSubHeadingListStart
{{#each @root.certificates}}
    \resumeProjectHeading
      {\textbf{ {{escapeLaTeX name}} }{{#if issuer}} $|$ \textit{\small {{escapeLaTeX issuer}} }{{/if}} }{ {{#if date}}{{formatDate date}}{{/if}} }
{{#if url}}
      \resumeItemListStart
        \resumeItem{\href{ {{url}} }{\myuline{Ver certificado}} }
      \resumeItemListEnd
{{/if}}
{{/each}}
  \resumeSubHeadingListEnd
{{/if}}
{{else if (eq this "publications")}}
{{#if (notEmpty @root.publications)}}
\section{PUBLICACIONES}
  \resumeSubHeadingListStart
{{#each @root.publications}}
    \resumeProjectHeading
      {\textbf{ {{escapeLaTeX name}} }{{#if publisher}} $|$ \textit{\small {{escapeLaTeX publisher}} }{{/if}} }{ {{#if releaseDate}}{{formatDate releaseDate}}{{/if}} }
{{#if summary}}
      \resumeItemListStart
        \resumeItem{ {{escapeLaTeX summary}} }
      \resumeItemListEnd
{{/if}}
{{/each}}
  \resumeSubHeadingListEnd
{{/if}}
{{else if (eq this "interests")}}
{{#if (notEmpty @root.interests)}}
\section{INTERESES}
 \begin{itemize}[leftmargin=0in, label={}]
    \small{\item{
{{#each @root.interests}}
     \textbf{ {{escapeLaTeX name}} }{{#if (notEmpty keywords)}}{: {{join keywords ", "}} }\vspace{2pt} \\{{else}}\\ {{/if}}
{{/each}}
    }}
 \end{itemize}
{{/if}}
{{else if (eq this "references")}}
{{#if (notEmpty @root.references)}}
\section{REFERENCIAS}
  \resumeSubHeadingListStart
{{#each @root.references}}
    \resumeProjectHeading
      {\textbf{ {{escapeLaTeX name}} }}{}
{{#if reference}}
      \resumeItemListStart
        \resumeItem{ {{escapeLaTeX reference}} }
      \resumeItemListEnd
{{/if}}
{{/each}}
  \resumeSubHeadingListEnd
{{/if}}
{{/if}}
{{/each}}

%-------------------------------------------
\end{document}
